 const market=window.FeatureMarket.create(),view={panel,market,state:{server:'europe'},active:()=>active,activate(){active=true;oldServer=$('server').value;view.state.server=oldServer;load();$('craft-content').hidden=true;panel.hidden=false;document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));view.render();view.refresh(false);},deactivate(){if(!active)return;active=false;request++;market.cancel();panel.hidden=true;$('craft-content').hidden=false;$('server').value=oldServer;},render(){if(view.state.server!==cfg?.server)load();fillPicker();specific();sync();renderResults();},async refresh(force){if(!active)return;const seq=++request,server=view.state.server,plans=[makePlan(cfg),...saved.records.filter(r=>r.mode===mode&&r.server===server).slice(-10).map(r=>makePlan(r.config))],ids=plans.flatMap(p=>[...(p.inputs||[]),...(p.outputs||[]),...(p.seedStock?[p.seedStock]:[])].map(x=>x.id));$(id('market')).textContent='Загружаем цены вещей и материалов…';const message=await market.load(server,ids,force);if(active&&seq===request&&server===view.state.server){$(id('market')).textContent=message||'Цены и история продаж обновлены.';renderResults();}}};
