 function fillPicker(){const text=$(id('search')).value.toLocaleLowerCase('ru-RU'),list=catalogs[mode].filter(r=>(r.name+' '+r.id).toLocaleLowerCase('ru-RU').includes(text)).slice(0,200),current=catalogs[mode].find(r=>r.id===cfg.item);if(!list.some(r=>r.id===current?.id)&&current)list.unshift(current);$(id('item')).innerHTML=list.map(r=>opt(r.id,r.name+' · '+r.id)).join('');$(id('item')).value=cfg.item;selection=current;$(id('selected')).innerHTML=window.ItemIcons.image(cfg.item,Number(cfg.quality)||1,40)+'<span>'+esc(current?.name||name(cfg.item))+'</span>';}
