 if(mode==='enchant'){const targets=[1,2,3].map(e=>base+'@'+e).filter(to=>E.route(cfg.item,to,X));if(!targets.includes(cfg.target))cfg.target=targets[0];html=select('До какого зачарования','target',targets.map(to=>opt(to,'.'+to.split('@')[1])).join(''))+field('Дополнительные расходы / вещь','fee',cfg.fee)+'<p class="hint">Руны → души → реликвии. Качество сохраняется. Фокус и возврат материалов при зачаровании не применяются. .4 требует отдельного крафта.</p>';}
 if(mode==='salvage'){html=field('Прочность вещи, %','condition',cfg.condition,'max="100"')+field('Возвращается материалов, %','salvageRate',cfg.salvageRate,'max="100"')+field('Серебро из окна разборки / вещь','silver',cfg.silver)+field('Дополнительные расходы / вещь','fee',cfg.fee)+`<p class="hint">Базовая оценка: 20% материалов с поправкой на прочность. Округляем вниз на каждую вещь. Неизвестные возвраты артефактов в доход не включаются. Уточните выход по окну разборки:</p>`+(X.salvage[cfg.item]||[]).map(m=>`<label class="field">${esc(name(m.id))} / одну вещь<input type="number" min="0" step="0.01" data-econ-yield="${esc(m.id)}" value="${Object.hasOwn(cfg.yields,m.id)?cfg.yields[m.id]:''}" placeholder="Автоматически"></label>`).join('');}
 if(mode==='mounts'){const b=X.breeders.find(b=>b.grown===selection.grown);html=select('Что делаем','mountMode',opt('saddle','Купить взрослого и изготовить маунта')+(b?opt('grown','Вырастить и продать взрослого')+opt('full','Вырастить и изготовить маунта'):''))+field('Изготовление: расход станка / маунт','fee',cfg.fee);if(b&&cfg.mountMode!=='saddle'){const feeds=b.foodCategory==='meat'?['T3_MEAT','T4_MEAT','T5_MEAT','T6_MEAT','T7_MEAT','T8_MEAT']:window.IslandData.crops.filter(c=>c.kind==='crop').map(c=>c.id);if(!feeds.includes(cfg.feed))cfg.feed=feeds[0];html+=check('Есть премиум: рост вдвое быстрее','premium')+select('Корм','feed',feeds.map(f=>opt(f,name(f))).join(''))+field('Корма на одного зверя за весь рост','feedQty',cfg.feedQty,'placeholder="Укажите расход из игры"')+field('Часов на выращивание (пусто — по рецепту)','growHours',cfg.growHours)+field('Уходов фокусом на каждого зверя','nurtures',cfg.nurtures,`max="${b.actions}" step="1"`)+field('Фокус на один уход у выбранного персонажа','nurtureFocus',cfg.nurtureCosts[profile()+'|'+cfg.item]??b.focus)+check('Повторять цикл: оставить молодняк на замену','repeat')+check('Продавать избыток молодняка','sellBabies')+field('Новые вложения: пастбище / питомник','investment',cfg.investment)+`<p class="hint">${esc(b.name)}: ${fmt(b.hours/(cfg.premium?2:1))} ч. роста, базовый приплод ${fmt(b.offspring*100,2)}%, до ${b.actions} уходов по +${fmt(b.nurtureBonus*100,2)}%. Приплод — среднее ожидание, отдельная партия может дать другой результат. Корм указывайте за весь рост, включая все кормления; недокорм продлевает цикл. Начальный запас молодняка считается вложением при повторных циклах.</p>`;}html+='<p class="hint">Цена готового маунта учитывает выбранное качество. Выбранное качество — сценарий продажи: при изготовлении оно не гарантировано. Для изготовления возврат не закладывается; корм, взрослый зверь и материалы седла оцениваются отдельно.</p>';}
